export interface KpiSummary {
  totalSales: number;
  totalCustomers: number;
  averageSpend: number;
  salesGrowthRate: number;
  customerGrowthRate: number;
  spendGrowthRate: number;
}

export type PeriodFilter = 'all' | 'first-half' | 'second-half' | 'recent-3m';

export type ChartMetric = 'all' | 'sales' | 'customers' | 'averageSpend';

export type SortOrder = 'asc' | 'desc';

export type SortKey =
