export type TableSortKey = SortKey;

export interface SortConfig {
  key: SortKey;
  order: SortOrder;
}

export type TableSortConfig = SortConfig;

export interface FilterOption<T extends string> {
  key: T;
  label: string;
  description?: string;
}

export type PeriodOption = FilterOption<PeriodFilter>;
export type ChartMetricOption = FilterOption<ChartMetric>;

