export const calculateGrowthRate = (
  current: number | undefined | null,
  previous: number | undefined | null
): number => {
  if (
    current === undefined ||
    current === null ||
    previous === undefined ||
    previous === null ||
    previous === 0 ||
    Number.isNaN(current) ||
    Number.isNaN(previous)
  ) {
    return 0;
  }
  return Number((((current - previous) / previous) * 100).toFixed(1));
};

export const filterMonthlyData = (
  data: MonthlyData[] = [],
  filter: PeriodFilter
): MonthlyData[] => {
  if (!Array.isArray(data) || data.length === 0) {
    return [];
  }

  switch (filter) {
    case 'first-half':
      return data.slice(0, Math.min(6, data.length));
    case 'second-half':
      return data.slice(Math.min(6, data.length), 12);
    case 'recent-3m':
      return data.slice(-Math.min(3, data.length));
    case 'all':
    default:
      return [...data];
  }
};

export const calculateKpiSummary = (data: MonthlyData[] = []): KpiSummary => {
  if (!Array.isArray(data) || data.length === 0) {
    return {
      totalSales: 0,
      totalCustomers: 0,
      averageSpend: 0,
      salesGrowthRate: 0,
      customerGrowthRate: 0,
      spendGrowthRate: 0
    };
  }

  const totalSales = data.reduce((acc, cur) => acc + (cur.sales || 0), 0);
  const totalCustomers = data.reduce((acc, cur) => acc + (cur.customers || 0), 0);
  const averageSpend = totalCustomers > 0 ? Math.round(totalSales / totalCustomers) : 0;

  let salesGrowthRate = 0;
  let customerGrowthRate = 0;
  let spendGrowthRate = 0;

  if (data.length >= 2) {
    const current = data[data.length - 1];
    const previous = data[data.length - 2];

    salesGrowthRate = calculateGrowthRate(current.sales, previous.sales);
    customerGrowthRate = calculateGrowthRate(current.customers, previous.customers);
    spendGrowthRate = calculateGrowthRate(current.averageSpend, previous.averageSpend);
  }

  return {
    totalSales,
    totalCustomers,
    averageSpend,
    salesGrowthRate,
    customerGrowthRate,
    spendGrowthRate
  };
};

import { KpiSummary } from '../types';

interface KpiCardsProps {
  summary?: KpiSummary;
}

const formatNumber = (num: number | undefined | null): string => {
  if (num == null || Number.isNaN(num)) {
    return '0';
  }
  return num.toLocaleString('ja-JP');
};

const getRateStatus = (
  rate: number | undefined | null,
  positiveLabel: string,
  negativeLabel: string
) => {
  const safeRate = rate == null || Number.isNaN(rate) ? 0 : rate;

  if (safeRate > 0) {
    return {
      badgeText: positiveLabel,
      signText: `+${safeRate}%`,
      symbol: '↑',
      className: 'kpi-positive'
    };
  }

  if (safeRate < 0) {
    return {
      badgeText: negativeLabel,
      signText: `${safeRate}%`,
      symbol: '↓',
      className: 'kpi-negative'
    };
  }

  return {
    badgeText: '横ばい',
    signText: '±0%',
    symbol: '→',
    className: ''
  };
};

const KpiCards = ({ summary }: KpiCardsProps) => {
  const safeSummary: KpiSummary = summary ?? {
    totalSales: 0,
    totalCustomers: 0,
    averageSpend: 0,
    salesGrowthRate: 0,
    customerGrowthRate: 0,
    spendGrowthRate: 0
  };

  const salesStatus = getRateStatus(safeSummary.salesGrowthRate, '好調', '要改善');
  const customerStatus = getRateStatus(safeSummary.customerGrowthRate, '増加', '減少');
  const spendStatus = getRateStatus(safeSummary.spendGrowthRate, '上昇', '下降');

  const cards = [
    {
      title: '総売上高',
      value: formatNumber(safeSummary.totalSales),
      unit: '円',
      status: salesStatus
    },
    {
      title: '総客数',
      value: formatNumber(safeSummary.totalCustomers),
      unit: '人',
      status: customerStatus
    },
    {
      title: '平均客単価',
      value: formatNumber(safeSummary.averageSpend),
      unit: '円',
      status: spendStatus
    }
  ];

  return (
    <div className="kpi-grid">
      {cards.map((card) => (
        <div key={card.title} className="kpi-card">
          <div className="kpi-card-header">
            <span className="kpi-label">{card.title}</span>
            <span className="kpi-badge">{card.status.badgeText}</span>
          </div>
          <div className="kpi-value-row">
            <span className="kpi-value">{card.value}</span>
            <span className="kpi-unit">{card.unit}</span>
          </div>
          <div className={`kpi-compare ${card.status.className}`.trim()}>
            <span>前月比: {card.status.symbol} {card.status.signText}</span>
          </div>
        </div>
      ))}
    </div>
  );
};

export default KpiCards;

import {
  ResponsiveContainer,
  ComposedChart,
  Bar,
  Line,
  XAxis,
  YAxis,
  CartesianGrid,
  Tooltip,
  Legend
} from 'recharts';
import { MonthlyData, ChartMetric } from '../types';

interface ChartsProps {
  data?: MonthlyData[];
  activeMetric: ChartMetric;
  onMetricChange: (metric: ChartMetric) => void;
}

const CHART_COLORS = {
  sales: '#3b82f6',
  targetSales: '#ef4444',
  customers: '#10b981',
  averageSpend: '#f59e0b'
} as const;

const Charts = ({
  data = [],
  activeMetric,
  onMetricChange
}: ChartsProps) => {
  const metricOptions: { key: ChartMetric; label: string }[] = [
    { key: 'all', label: '全体（複合）' },
    { key: 'sales', label: '売上推移' },
    { key: 'customers', label: '客数推移' },
    { key: 'averageSpend', label: '客単価推移' }
  ];

  const formatSalesTooltip = (val: number) => `${(val ?? 0).toLocaleString('ja-JP')} 円`;
  const formatCustomerTooltip = (val: number) => `${(val ?? 0).toLocaleString('ja-JP')} 人`;
  const formatYAxisSales = (val: number) => `${((val ?? 0) / 10000).toLocaleString('ja-JP')}万`;

  const hasData = Array.isArray(data) && data.length > 0;

  return (
    <div className="charts-section">
      <div className="chart-card">
        <div className="chart-header">
          <h2 className="chart-title">月別推移トレンド</h2>
          <div className="chart-controls">
            {metricOptions.map((opt) => (
              <button
                key={opt.key}
                type="button"
                className={`chart-metric-btn ${
                  activeMetric === opt.key ? 'chart-metric-btn-active' : ''
                }`}
                onClick={() => onMetricChange(opt.key)}
              >
                {opt.label}
              </button>
            ))}
          </div>
        </div>

        <div style={{ width: '100%', height: 380 }}>
          {!hasData ? (
            <div
              style={{
                width: '100%',
                height: '100%',
                display: 'flex',
                alignItems: 'center',
                justifyContent: 'center',
                color: 'var(--text-muted)',
                fontSize: '14px'
              }}
            >
              データがありません
            </div>
          ) : (
            <ResponsiveContainer width="100%" height="100%">
              <ComposedChart
                data={data}
                margin={{ top: 20, right: 30, left: 20, bottom: 20 }}
              >
                <CartesianGrid strokeDasharray="3 3" vertical={false} opacity={0.3} />
                <XAxis dataKey="month" tick={{ fontSize: 13 }} />

                {(activeMetric === 'all' || activeMetric === 'sales') && (
                  <YAxis
                    yAxisId="salesAxis"
                    orientation="left"
                    tickFormatter={formatYAxisSales}
                    tick={{ fontSize: 12 }}
                  />
                )}

                {activeMetric === 'all' && (
                  <YAxis
                    yAxisId="customerAxis"
                    orientation="right"
                    tickFormatter={(val) => `${val}人`}
                    tick={{ fontSize: 12 }}
                  />
                )}

                {activeMetric === 'customers' && (
                  <YAxis
                    yAxisId="customerAxis"
                    orientation="left"
                    tickFormatter={(val) => `${val}人`}
                    tick={{ fontSize: 12 }}
                  />
                )}

                {activeMetric === 'averageSpend' && (
                  <YAxis
                    yAxisId="spendAxis"
                    orientation="left"
                    tickFormatter={(val) => `${val}円`}
                    tick={{ fontSize: 12 }}
                    domain={['dataMin - 200', 'dataMax + 200']}
                  />
                )}

                <Tooltip
                  formatter={(value: number, name: string) => {
                    if (name === '売上高' || name === '目標売上') {
                      return [formatSalesTooltip(value), name];
                    }
                    if (name === '客数') {
                      return [formatCustomerTooltip(value), name];
                    }
                    return [`${(value ?? 0).toLocaleString('ja-JP')} 円`, name];
                  }}
                />
                <Legend verticalAlign="top" height={36} />

                {(activeMetric === 'all' || activeMetric === 'sales') && (
                  <Bar
                    yAxisId="salesAxis"
                    dataKey="sales"
                    name="売上高"
                    fill={CHART_COLORS.sales}
                    radius={[4, 4, 0, 0]}
                    barSize={32}
                  />
                )}

                {(activeMetric === 'all' || activeMetric === 'sales') && (
                  <Line
                    yAxisId="salesAxis"
                    type="monotone"
                    dataKey="targetSales"
                    name="目標売上"
                    stroke={CHART_COLORS.targetSales}
                    strokeDasharray="4 4"
                    strokeWidth={2}
                    dot={{ r: 3 }}
                  />
                )}

                {(activeMetric === 'all' || activeMetric === 'customers') && (
                  <Line
                    yAxisId="customerAxis"
                    type="monotone"
                    dataKey="customers"
                    name="客数"
                    stroke={CHART_COLORS.customers}
                    strokeWidth={2}
                    dot={{ r: 4 }}
                  />
                )}

                {activeMetric === 'averageSpend' && (
                  <Line
                    yAxisId="spendAxis"
                    type="monotone"
                    dataKey="averageSpend"
                    name="平均客単価"
                    stroke={CHART_COLORS.averageSpend}
                    strokeWidth={2}
                    dot={{ r: 4 }}
                  />
                )}
              </ComposedChart>
            </ResponsiveContainer>
          )}
        </div>
      </div>
    </div>
  );
};

export default Charts;

import { useState, useMemo } from 'react';
import { PeriodFilter, ChartMetric, TableSortKey, TableSortConfig } from './types';
import { mockMonthlyData, filterMonthlyData, calculateKpiSummary } from './mockData';
import KpiCards from './components/KpiCards';
import Charts from './components/Charts';
import './index.css';

const calculateAchievementRate = (sales: number, targetSales: number): number => {
  if (!targetSales || targetSales === 0) return 0;
  return Number(((sales / targetSales) * 100).toFixed(1));
};

const parseMonthNumber = (monthStr: string): number => {
  const match = monthStr.match(/\d+/);
  return match ? parseInt(match[0], 10) : 0;
};

const App = () => {
  const [period, setPeriod] = useState<PeriodFilter>('all');
  const [activeMetric, setActiveMetric] = useState<ChartMetric>('all');
  const [sortConfig, setSortConfig] = useState<TableSortConfig>({ key: 'month', order: 'asc' });

  const filteredData = useMemo(() => {
    return filterMonthlyData(mockMonthlyData, period);
  }, [period]);

  const kpiSummary = useMemo(() => {
    return calculateKpiSummary(filteredData);
  }, [filteredData]);

  const tableRows = useMemo(() => {
    const list = filteredData.map((row) => ({
      ...row,
      achievementRate: calculateAchievementRate(row.sales, row.targetSales)
    }));

    list.sort((a, b) => {
      let comparison = 0;
      if (sortConfig.key === 'month') {
        comparison = parseMonthNumber(a.month) - parseMonthNumber(b.month);
      } else {
        comparison = a[sortConfig.key] - b[sortConfig.key];
      }
      return sortConfig.order === 'asc' ? comparison : -comparison;
    });

    return list;
  }, [filteredData, sortConfig]);

  const tableSummary = useMemo(() => {
    const totalSales = filteredData.reduce((acc, cur) => acc + (cur.sales || 0), 0);
    const totalTarget = filteredData.reduce((acc, cur) => acc + (cur.targetSales || 0), 0);
    const totalCustomers = filteredData.reduce((acc, cur) => acc + (cur.customers || 0), 0);
    const overallAchievement = calculateAchievementRate(totalSales, totalTarget);
    const weightedAverageSpend = totalCustomers > 0 ? Math.round(totalSales / totalCustomers) : 0;

    return {
      totalSales,
      totalTarget,
      overallAchievement,
      totalCustomers,
      weightedAverageSpend
    };
  }, [filteredData]);

  const handleSort = (key: TableSortKey) => {
    setSortConfig((prev) => {
      if (prev.key === key) {
        return {
          key,
          order: prev.order === 'asc' ? 'desc' : 'asc'
        };
      }
      return {
        key,
        order: 'desc'
      };
    });
  };

  const getSortIcon = (key: TableSortKey) => {
    if (sortConfig.key !== key) return ' ↕';
    return sortConfig.order === 'asc' ? ' ↑' : ' ↓';
  };

  const periodOptions: { key: PeriodFilter; label: string }[] = [
    { key: 'all', label: '通期（1月〜12月）' },
    { key: 'first-half', label: '上半期（1月〜6月）' },
    { key: 'second-half', label: '下半期（7月〜12月）' },
    { key: 'recent-3m', label: '直近3ヶ月' }
  ];

  return (
    <div className="dashboard-container">
      <header className="dashboard-header">
        <div className="header-title-group">
          <h1 className="header-title">店舗売上・実績分析ダッシュボード</h1>
          <p className="header-subtitle">
            売上高、客数、客単価の推移と目標達成状況を可視化・分析します
          </p>
        </div>

        <div className="filter-bar">
          <div className="filter-group">
            {periodOptions.map((opt) => (
              <button
                key={opt.key}
                type="button"
                className={`filter-btn ${period === opt.key ? 'filter-btn-active' : ''}`}
                onClick={() => setPeriod(opt.key)}
              >
                {opt.label}
              </button>
            ))}
          </div>
        </div>
      </header>

      <main>
        <KpiCards summary={kpiSummary} />

        <Charts
          data={filteredData}
          activeMetric={activeMetric}
          onMetricChange={setActiveMetric}
        />

        <section className="table-section">
          <div className="table-card">
            <div className="table-header">
              <h2 className="chart-title">月別詳細実績一覧</h2>
            </div>
            <div className="table-responsive">
              <table className="data-table">
                <thead>
                  <tr>
                    <th
                      className="text-center"
                      onClick={() => handleSort('month')}
                      style={{ cursor: 'pointer', userSelect: 'none' }}
                      title="月度で並び替え"
                    >
                      月度{getSortIcon('month')}
                    </th>
                    <th
                      className="text-right"
                      onClick={() => handleSort('sales')}
                      style={{ cursor: 'pointer', userSelect: 'none' }}
                      title="売上高で並び替え"
                    >
                      売上高 (円){getSortIcon('sales')}
                    </th>
                    <th
                      className="text-right"
                      onClick={() => handleSort('targetSales')}
                      style={{ cursor: 'pointer', userSelect: 'none' }}
                      title="目標売上で並び替え"
                    >
                      目標売上 (円){getSortIcon('targetSales')}
                    </th>
                    <th
                      className="text-center"
                      onClick={() => handleSort('achievementRate')}
                      style={{ cursor: 'pointer', userSelect: 'none' }}
                      title="目標達成率で並び替え"
                    >
                      目標達成率{getSortIcon('achievementRate')}
                    </th>
                    <th
                      className="text-right"
                      onClick={() => handleSort('customers')}
                      style={{ cursor: 'pointer', userSelect: 'none' }}
                      title="客数で並び替え"
                    >
                      客数 (人){getSortIcon('customers')}
                    </th>
                    <th
                      className="text-right"
                      onClick={() => handleSort('averageSpend')}
                      style={{ cursor: 'pointer', userSelect: 'none' }}
                      title="客単価で並び替え"
                    >
                      客単価 (円){getSortIcon('averageSpend')}
                    </th>
                  </tr>
                </thead>
                <tbody>
                  {tableRows.map((row) => {
                    const isTargetMet = row.achievementRate >= 100;

                    return (
                      <tr key={row.month}>
                        <td className="text-center">{row.month}</td>
                        <td className="text-right">{row.sales.toLocaleString('ja-JP')}</td>
                        <td className="text-right">{row.targetSales.toLocaleString('ja-JP')}</td>
                        <td className="text-center">
                          <span className={isTargetMet ? 'badge-up' : 'badge-down'}>
                            {row.achievementRate}%
                          </span>
                        </td>
                        <td className="text-right">{row.customers.toLocaleString('ja-JP')}</td>
                        <td className="text-right">{row.averageSpend.toLocaleString('ja-JP')}</td>
                      </tr>
                    );
                  })}
                </tbody>
                <tfoot>
                  <tr style={{ backgroundColor: '#f1f5f9', fontWeight: 600 }}>
                    <td className="text-center">合計 / 全体平均</td>
                    <td className="text-right">{tableSummary.totalSales.toLocaleString('ja-JP')}</td>
                    <td className="text-right">{tableSummary.totalTarget.toLocaleString('ja-JP')}</td>
                    <td className="text-center">
                      <span className={tableSummary.overallAchievement >= 100 ? 'badge-up' : 'badge-down'}>
                        {tableSummary.overallAchievement}%
                      </span>
                    </td>
                    <td className="text-right">{tableSummary.totalCustomers.toLocaleString('ja-JP')}</td>
                    <td className="text-right">{tableSummary.weightedAverageSpend.toLocaleString('ja-JP')}</td>
                  </tr>
                </tfoot>
              </table>
            </div>
          </div>
        </section>
      </main>
    </div>
  );
};

export default App;
